-- Catalogue Keune du salon, relevé sur maisonkeune.tn (distributeur Keune en
-- Tunisie, déjà cité en partenaire dans le pied de la boutique).
--
-- 202 références : les tailles d'un même soin sont des produits distincts, car
-- la table n'a qu'un prix par ligne. Les colorations restent un seul produit,
-- toutes leurs nuances étant au même prix ; leur description dit combien de
-- nuances existent et invite à préciser la sienne en note de commande.
--
-- Les photos ont été rapatriées dans le bucket `media` du projet : la boutique
-- ne dépend d'aucun site tiers pour s'afficher.
--
-- Le stock n'est pas publié par la source : 12 pour un produit disponible, 0
-- pour un produit épuisé. C'est un point de départ à corriger dans le panneau.
-- Une réexécution ne réécrit donc PAS le stock, qui appartient au salon.

on conflict (slug) do update
  set nom         = excluded.nom,
      marque      = excluded.marque,
      description = excluded.description,
      prix        = excluded.prix,
      ancien_prix = excluded.ancien_prix,
      image_url   = excluded.image_url,
      categorie   = excluded.categorie,
      ordre       = excluded.ordre,
      actif       = excluded.actif;

-- Les six produits de démonstration semés en 0006 ne sont pas ceux du salon :
-- on les range après le vrai catalogue plutôt que de les effacer, le salon
-- décidera lui-même de les désactiver depuis /admin/produits.
update produits
   set ordre = 1000 + ordre
 where ordre < 100
   and slug in ('serum-eclat-vitamine-c', 'creme-hydratante-jour',
                'huile-precieuse-cheveux', 'masque-reparateur',
                'gommage-corps-argan', 'bougie-massage');
