insert into produits
  (slug, nom, marque, description, prix, ancien_prix, image_url, categorie, stock, ordre, actif)
values
  ('1922-by-j-m-keune-beard-balm', 'Beard Balm', '1922 by J.M. Keune', 'Découvrez notre baume à barbe hydratant au beurre de karité, conçu pour une tenue légère et un fini naturel. Enrichi en huiles nourrissantes et cire d''abeille, il hydrate, assouplit et protège votre barbe et votre peau pour un look soigné et rafraîchi.', 132.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/1922-by-j-m-keune-beard-balm.webp', 'corps', 12, 101, true),
  ('1922-by-j-m-keune-classic-gel', 'Classic Gel', '1922 by J.M. Keune', '', 82.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/1922-by-j-m-keune-classic-gel.webp', 'cheveux', 12, 102, true),
  ('1922-by-j-m-keune-deep-cleansing-shampooing-1000ml', 'Deep-Cleansing Shampooing 1000ml', '1922 by J.M. Keune', 'Shampooing Lavant Intense 1922 by J.M. Keune : nettoie en profondeur, hydrate et renforce les cheveux. Formulé avec de la créatine pour limiter la casse et de l''extrait de bambou pour épaissir la chevelure. Idéal pour les cheveux et cuirs chevelus gras.', 176.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/1922-by-j-m-keune-deep-cleansing-shampooing-1000ml.webp', 'cheveux', 12, 103, true),
  ('1922-by-j-m-keune-deep-cleansing-shampooing-250ml', 'Deep-Cleansing Shampooing 250ml', '1922 by J.M. Keune', 'Shampooing Lavant Intense 1922 by J.M. Keune : nettoie en profondeur, hydrate et renforce les cheveux. Formulé avec de la créatine pour limiter la casse et de l''extrait de bambou pour épaissir la chevelure. Idéal pour les cheveux et cuirs chevelus gras.', 99.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/1922-by-j-m-keune-deep-cleansing-shampooing-250ml.webp', 'cheveux', 12, 104, true),
  ('1922-by-j-m-keune-essential-apres-shampooing', 'Essential Après-shampooing', '1922 by J.M. Keune', 'Essential Shampooing 1922 by J.M. Keune : un tout-en-un pour cheveux, barbe et corps. Enrichi en créatine, il fortifie, épaissit et nourrit les cheveux. Idéal pour un usage quotidien, il hydrate les cuirs chevelus et cheveux secs.', 104.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/1922-by-j-m-keune-essential-apres-shampooing.webp', 'cheveux', 12, 105, true),
  ('1922-by-j-m-keune-essential-shampooing-1000ml', 'Essential Shampooing 1000ml', '1922 by J.M. Keune', 'Shampooing Essentiel 1922 by J.M. Keune : un soin tout-en-un pour cheveux, barbe et corps. Enrichi en créatine et bambou, il renforce, épaissit et nourrit. Idéal pour un usage quotidien sur cheveux et cuir chevelu secs.', 176.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/1922-by-j-m-keune-essential-shampooing-1000ml.webp', 'cheveux', 12, 106, true),
  ('1922-by-j-m-keune-essential-shampooing-250ml', 'Essential Shampooing 250ml', '1922 by J.M. Keune', 'Shampooing Essentiel 1922 by J.M. Keune : un soin tout-en-un pour cheveux, barbe et corps. Enrichi en créatine et bambou, il renforce, épaissit et nourrit. Idéal pour un usage quotidien sur cheveux et cuir chevelu secs.', 99.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/1922-by-j-m-keune-essential-shampooing-250ml.webp', 'cheveux', 12, 107, true),
  ('1922-by-j-m-keune-fortifying-lotion', 'Fortifying Lotion', '1922 by J.M. Keune', 'Lotion Fortifiante 1922 by J.M. Keune : stimule la croissance des cheveux de 25 % en 4 jours grâce aux liposomes. La biotine renforce la fibre capillaire, tandis que le ginseng, l''eucalyptus et la caféine revitalisent et dynamisent le cuir chevelu.', 132.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/1922-by-j-m-keune-fortifying-lotion.webp', 'cheveux', 12, 108, true),
  ('1922-by-j-m-keune-fortifying-shampooing-1000ml', 'Fortifying Shampooing 1000ml', '1922 by J.M. Keune', 'Qui ne rêve pas de cheveux plus épais ? Les cheveux délicats, fins et ternes ont besoin du genre d''attention que propose notre Shampooing fortifiant.', 176.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/1922-by-j-m-keune-fortifying-shampooing-1000ml.webp', 'cheveux', 12, 109, true),
  ('1922-by-j-m-keune-fortifying-shampooing-250ml', 'Fortifying Shampooing 250ml', '1922 by J.M. Keune', 'Qui ne rêve pas de cheveux plus épais ? Les cheveux délicats, fins et ternes ont besoin du genre d''attention que propose notre Shampooing fortifiant.', 99.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/1922-by-j-m-keune-fortifying-shampooing-250ml.webp', 'cheveux', 12, 110, true),
  ('1922-by-j-m-keune-matte-measure', 'Matte Measure', '1922 by J.M. Keune', 'Matte Measure est une crème modelante polyvalente offrant une tenue moyenne et un fini mat. Idéale pour des looks texturés, elle permet de remodeler les cheveux facilement. Pour un style décoiffé ou structuré, elle assure une tenue durable sans alourdir.', 82.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/1922-by-j-m-keune-matte-measure.webp', 'cheveux', 12, 111, true),
  ('1922-by-j-m-keune-original-pomade', 'Original Pomade', '1922 by J.M. Keune', 'L''Original Pomade est un coiffant intemporel offrant une tenue forte et une finition brillante, idéale pour les cheveux courts à mi-longs. Enrichie en créatine, elle renforce et protège les cheveux tout en garantissant un style sophistiqué et durable.', 82.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/1922-by-j-m-keune-original-pomade.webp', 'cheveux', 12, 112, true),
  ('1922-by-j-m-keune-premier-paste', 'Premier Paste', '1922 by J.M. Keune', 'La Premier Paste assure une tenue forte et une brillance intense. Enrichie en créatine et en extrait de chanvre, elle renforce et nourrit les cheveux. Polyvalente, elle s''utilise seule ou en finition, idéale pour des styles plaqués, texturés ou gominés.', 82.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/1922-by-j-m-keune-premier-paste.webp', 'cheveux', 12, 113, true),
  ('1922-by-j-m-keune-premium-clay', 'Premium Clay', '1922 by J.M. Keune', 'La Premium Clay offre une tenue forte et un fini mat, idéal pour texturiser et définir les cheveux courts à mi-longs. Enrichie en créatine, elle renforce et revitalise les cheveux tout en garantissant un style précis et durable.', 82.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/1922-by-j-m-keune-premium-clay.webp', 'cheveux', 12, 114, true),
  ('1922-by-j-m-keune-purifying-shampooing-1000ml', 'Purifying Shampooing 1000ml', '1922 by J.M. Keune', 'Shampooing Lavant Intense 1922 by J.M. Keune : nettoie en profondeur tout en hydratant et renforçant les cheveux. Enrichi en créatine pour réduire la casse et en extrait de bambou pour épaissir la chevelure. Idéal pour les cuirs chevelus et cheveux gras.', 176.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/1922-by-j-m-keune-purifying-shampooing-1000ml.webp', 'cheveux', 12, 115, true),
  ('1922-by-j-m-keune-purifying-shampooing-250ml', 'Purifying Shampooing 250ml', '1922 by J.M. Keune', 'Shampooing Lavant Intense 1922 by J.M. Keune : nettoie en profondeur tout en hydratant et renforçant les cheveux. Enrichi en créatine pour réduire la casse et en extrait de bambou pour épaissir la chevelure. Idéal pour les cuirs chevelus et cheveux gras.', 99.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/1922-by-j-m-keune-purifying-shampooing-250ml.webp', 'cheveux', 12, 116, true),
  ('1922-by-j-m-keune-refreshing-apres-shampooing-1000ml', 'Refreshing Après-shampooing 1000ml', '1922 by J.M. Keune', 'Après-shampooing fortifiant et rafraîchissant , parfait avec le Shampooing rafraîchissant 1922 by J.M. Keune. Enrichi en créatine pour réduire la casse, menthe poivrée et menthol pour stimuler le cuir chevelu, il renforce et revitalise les cheveux tout en offrant une sensation vivifiante.', 181.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/1922-by-j-m-keune-refreshing-apres-shampooing-1000ml.webp', 'cheveux', 12, 117, true),
  ('1922-by-j-m-keune-refreshing-apres-shampooing-250ml', 'Refreshing Après-shampooing 250ml', '1922 by J.M. Keune', 'Après-shampooing fortifiant et rafraîchissant , parfait avec le Shampooing rafraîchissant 1922 by J.M. Keune. Enrichi en créatine pour réduire la casse, menthe poivrée et menthol pour stimuler le cuir chevelu, il renforce et revitalise les cheveux tout en offrant une sensation vivifiante.', 104.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/1922-by-j-m-keune-refreshing-apres-shampooing-250ml.webp', 'cheveux', 12, 118, true),
  ('1922-by-j-m-keune-refreshing-shampooing-1000ml', 'Refreshing Shampooing 1000ml', '1922 by J.M. Keune', 'Shampooing rafraîchissant 1922 by J.M. Keune : idéal pour tous les types de cheveux, il renforce grâce à la créatine et nourrit avec l''extrait de graines de chanvre. La menthe poivrée et le menthol stimulent le cuir chevelu pour une fraîcheur revitalisante.', 176.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/1922-by-j-m-keune-refreshing-shampooing-1000ml.webp', 'cheveux', 12, 119, true),
  ('1922-by-j-m-keune-refreshing-shampooing-250ml', 'Refreshing Shampooing 250ml', '1922 by J.M. Keune', 'Shampooing rafraîchissant 1922 by J.M. Keune : idéal pour tous les types de cheveux, il renforce grâce à la créatine et nourrit avec l''extrait de graines de chanvre. La menthe poivrée et le menthol stimulent le cuir chevelu pour une fraîcheur revitalisante.', 99.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/1922-by-j-m-keune-refreshing-shampooing-250ml.webp', 'cheveux', 12, 120, true),
  ('1922-by-j-m-keune-strong-hold-wax', 'Strong Hold Wax', '1922 by J.M. Keune', 'La 1922 Strong Hold Wax assure une tenue forte et une brillance parfaite (facteur de brillance 8) pour un look impeccable toute la journée. Enrichie en créatine, elle nourrit et renforce les cheveux tout en diffusant le parfum emblématique de la gamme 1922 .', 82.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/1922-by-j-m-keune-strong-hold-wax.webp', 'cheveux', 12, 121, true),
  ('1922-by-j-m-keune-superior-shaving-cream', 'Superior Shaving Cream', '1922 by J.M. Keune', 'Obtenez un rasage doux et précis avec notre crème à raser Superior Shaving. Sa mousse onctueuse adoucit les poils et hydrate la peau grâce au bisabolol et à la glycérine. Idéale pour les peaux normales à sensibles, elle laisse une sensation agréable et apaisante.', 82.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/1922-by-j-m-keune-superior-shaving-cream.webp', 'corps', 12, 122, true),
  ('1922-by-j-m-keune-tough-texture', 'Tough Texture', '1922 by J.M. Keune', 'Un spray épaississant offrant une tenue moyenne et un fini mat. Créez un look texturé sans alourdir vos cheveux.', 82.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/1922-by-j-m-keune-tough-texture.webp', 'cheveux', 12, 123, true),
  ('air-wax', 'Air Wax', 'Keune', 'Notre cire légère en spray offre texture, définition et brillance sans alourdir. Sa formule ultra-fine et non grasse maîtrise les frisottis et convient à tous les types de cheveux. Parfumée au Bergamot Blush, elle garantit un fini naturel et élégant.', 121.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/air-wax.webp', 'cheveux', 12, 124, true),
  ('blonde-neutralizing-s-pray', 'Blonde Neutralizing S pray', 'Keune', 'Découvrez le spray neutralisant Ultimate Blonde, la solution professionnelle pour éliminer les reflets cuivrés. Pas de mélange nécessaire. Il suffit de vaporiser sur cheveux mouillés ou secs pour une action instantanée des pigments violets/bleus, révélant des nuances froides et des mèches cendrées.', 88.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/blonde-neutralizing-s-pray.webp', 'cheveux', 12, 125, true),
  ('keune-bond-fusion-phase-3', 'Bond Fusion Phase 3', 'Keune', 'Découvrez Home Bond Booster : un soin capillaire exclusif qui revitalise et nourrit en profondeur. Grâce à sa technologie de fusion de protéines, il renforce la structure interne des cheveux et offre des bienfaits jusqu''à 5 fois plus durables que les traitements classiques.', 165.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-bond-fusion-phase-3.webp', 'cheveux', 12, 126, true),
  ('clean-slate', 'Clean Slate', 'Keune', 'Clean Slate, le shampooing sec qui rafraîchit instantanément, absorbe l''excès de sébum et ajoute du volume. Idéal pour prolonger votre coiffure, il laisse un parfum Rhubarb Bloom et maintient une sensation de propreté entre deux lavages.', 67.375, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/clean-slate.webp', 'cheveux', 12, 127, true),
  ('keune-cleanse-mist', 'Cleanse Mist', 'Keune', 'Une brume neutralisante des métaux à usage professionnel avant la coloration, idéale pour tous les services de coloration et d''éclaircissement. Obtenez une couleur éclatante et fidèle tout en prévenant les dommages et la casse avec la Keune Cleanse Mist.', 220.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-cleanse-mist.webp', 'cheveux', 12, 128, true),
  ('confident-curl-leave-in-wavy', 'Confident Curl Leave-in Wavy', 'Keune', 'Sublimez vos ondulations avec notre crème sans rinçage. Enrichie en huile de coco et extrait de vinaigre, elle hydrate, protège et lisse les cuticules. Tenue légère, frisottis réduits et boucles définies pour un look éclatant. Idéale pour les cheveux 2A-2C.', 104.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/confident-curl-leave-in-wavy.webp', 'cheveux', 12, 129, true),
  ('fixer', 'FIXER', 'Keune', 'Fixer est une laque à fixation maximale qui maintient vos coiffures impeccables toute la journée. Convient à tous les types et longueurs de cheveux, elle assure une tenue longue durée. Parfumée Rhubarb Bloom pour une touche délicate.', 67.375, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/fixer.webp', 'cheveux', 12, 130, true),
  ('free-styler', 'Free Styler', 'Keune', 'Le Free Styler 360° offre une fixation moyenne ajustable jusqu''à 24 heures. Avec son spray innovant, elle permet une application sous tous les angles. Parfumée à Rhubarb Bloom, elle protège contre l''humidité et apporte brillance et contrôle.', 110.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/free-styler.webp', 'cheveux', 12, 131, true),
  ('hair-straightener', 'Hair Straightener', 'Keune', 'Le lisseur Keune Hair Straightener permet de lisser les cheveux bouclés, les rendant ainsi lisses et faciles à coiffer. Il contient de la phytokératine cationique (K+) et de la protéine de soie, ce qui rend les cheveux beaux et brillants.', 25.3, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/hair-straightener.webp', 'cheveux', 12, 132, true),
  ('hair-straightener-extra-forte', 'Hair Straightener Extra Forte', 'Keune', 'Transformez vos boucles en une chevelure lisse et soyeuse avec notre Hair Straightener, disponible en deux intensités. Enrichi en phytokératine (K+) et en protéines de soie, il répare la fibre capillaire tout en offrant un lissage durable et éclatant, sans nécessiter de lisseur.', 25.3, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/hair-straightener-extra-forte.webp', 'cheveux', 12, 133, true),
  ('high-rise', 'High Rise', 'Keune', 'High Rise booste instantanément le volume dès la racine grâce à sa formule légère enrichie en panthénol, protéines végétales et vitamine E. Il nourrit, renforce et protège les cheveux tout en offrant un parfum Rhubarb Bloom pour une chevelure aérienne et éclatante.', 67.375, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/high-rise.webp', 'cheveux', 12, 134, true),
  ('keune-long-strong-shampooing-1000ml', 'Long & Strong Shampooing 1000ml', 'Keune', 'Créez une texture aérée, facile à construire et une tenue durable avec la cire en spray N° 46. Cette brume de cire ultrafine ajoute une brillance et une définition naturelles à tous les types de cheveux, avec un fini non gras. Vous pouvez même l''utiliser pour lisser les frisottis et les cheveux rebelles.', 0.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-long-strong-shampooing-1000ml.webp', 'cheveux', 0, 135, false),
  ('keune-long-strong-shampooing-300ml', 'Long & Strong Shampooing 300ml', 'Keune', 'Créez une texture aérée, facile à construire et une tenue durable avec la cire en spray N° 46. Cette brume de cire ultrafine ajoute une brillance et une définition naturelles à tous les types de cheveux, avec un fini non gras. Vous pouvez même l''utiliser pour lisser les frisottis et les cheveux rebelles.', 0.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-long-strong-shampooing-300ml.webp', 'cheveux', 0, 136, false),
  ('magic-blond', 'Magic Blond', 'Keune', 'Keune Ultimate Blonde Magic Blonde Lifting Powder est une poudre décolorante sans poussière qui protège le cuir chevelu et les cheveux pendant le processus de décoloration.', 165.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/magic-blond.webp', 'cheveux', 12, 137, true),
  ('keune-miracle-elixir-keratin-booster', 'Miracle Elixir Keratin Booster', 'Keune', 'Associez l''élixir concentré à la kératine Keune à un masque capillaire Keune Care adapté aux besoins spécifiques des cheveux. Ce soin intensif renforce, nourrit et restaure la fibre capillaire, offrant des cheveux plus sains, plus doux et éclatants de brillance.', 275.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-miracle-elixir-keratin-booster.png', 'cheveux', 12, 138, true),
  ('power-paste', 'Power Paste', 'Keune', 'Notre pâte texturisante offre une tenue maximale et un fini super-mat résistant à l''eau. Idéale pour les cheveux courts à mi-longs, elle assure une fixation jusqu''à 48 heures*. Son parfum envoûtant Cardamon Spell sublime chaque coiffure.', 67.375, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/power-paste.webp', 'cheveux', 12, 139, true),
  ('resetter', 'Resetter', 'Keune', 'Le spray Resetter microbiome, enrichi en prébiotiques, romarin et bétaïne, protège de la chaleur jusqu''à 230°C. Il nourrit le cuir chevelu, renforce les fibres capillaires et équilibre le microbiome. Son parfum Violet Crush sublime l''expérience.', 67.375, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/resetter.webp', 'cheveux', 12, 140, true),
  ('keune-revive-balm-150ml', 'Revive Balm 150ml', 'Keune', 'Revive Balm de Keune est un soin sans rinçage qui préserve l''éclat de la couleur et renforce les cheveux après une coloration ou un éclaircissement. Remplacez votre après-shampooing ou masque habituel pour une protection intense, une couleur vibrante et une chevelure fortifiée.', 264.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-revive-balm-150ml.webp', 'cheveux', 12, 141, true),
  ('keune-revive-balm-50ml', 'Revive Balm 50ml', 'Keune', 'Revive Balm de Keune est un soin sans rinçage qui préserve l''éclat de la couleur et renforce les cheveux après une coloration ou un éclaircissement. Remplacez votre après-shampooing ou masque habituel pour une protection intense, une couleur vibrante et une chevelure fortifiée.', 176.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-revive-balm-50ml.webp', 'cheveux', 12, 142, true),
  ('rush-hour', 'Rush Hour', 'Keune', 'Rush Hour accélère le séchage, donne du volume et protège jusqu''à 230°C. Enrichi en Technologie Bond Fuser, il renforce les boucles et réduit le temps de coiffage. Son parfum Midnight Blossom sublime l''expérience. Nominé aux Swedish Beauty Awards 2025.', 67.375, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/rush-hour.webp', 'cheveux', 12, 143, true),
  ('spc-blonde-lift-powder', 'SPC Blonde Lift Powder', 'Keune', 'So Pure Color Blonde Lift Powder est un éclaircissant haute performance sans ammoniaque, enrichi en huile d''argan biologique. Formulé avec PhytoKératine, il reconstruit la structure interne des cheveux et les protège pendant le lifting, offrant un blond naturel, fort et sain.', 165.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/spc-blonde-lift-powder.webp', 'cheveux', 12, 144, true),
  ('keune-semi-color-60ml', 'Semi Color 60ml', 'Keune', 'Keune Semi Color est parfait pour une coloration initiale ou pour rafraîchir les longueurs et les pointes des cheveux. La coloration semi-permanente Semi Color est basée sur une formule unique et scientifiquement avancée. Disponible en 65 nuances — précisez la nuance souhaitée en note de commande.', 44.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-semi-color-60ml.webp', 'cheveux', 12, 145, true),
  ('semi-color-activator', 'Semi Color Activator', 'Keune', 'Keune Semi Color Activator est à utiliser avec Keune Semi Color, les couleurs semi-permanentes. Il assure un bon développement et une stabilité pour une couleur plus durable. Semi Color Activator est un révélateur spécial qui est utilisé avec Keune Semi Color.', 44.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/semi-color-activator.webp', 'cheveux', 12, 146, true),
  ('shine-therapy', 'Shine Therapy', 'Keune', 'Shine Therapy est un spray ultra-léger qui renforce la brillance jusqu''à 80 %* sans effet gras ni collant. Idéal pour la touche finale, il dompte l''électricité statique et laisse un fini lisse. Parfumé Rhubarb Bloom.', 55.671, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/shine-therapy.webp', 'cheveux', 12, 147, true),
  ('smooth-operator', 'Smooth Operator', 'Keune', 'Notre sérum ultra-léger réduit les frisottis et booste la brillance jusqu''à 89 %*. Enrichi en vitamine E et protéines végétales, il nourrit et protège les cheveux. Facile à appliquer, il convient à tous les types pour une chevelure lisse et éclatante.', 77.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/smooth-operator.webp', 'cheveux', 12, 148, true),
  ('so-pure-color-60ml', 'So Pure Color 60ml', 'Keune', 'So Pure Color vous permet de travailler avec des produits de coloration naturellement nourrissants et merveilleusement parfumés, contenant des huiles biologiques d''argan, de jasmin et de bois de santal. Disponible en 58 nuances — précisez la nuance souhaitée en note de commande.', 49.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/so-pure-color-60ml.webp', 'cheveux', 12, 149, true),
  ('stardust', 'Stardust', 'Keune', 'Stardust est une poudre légère qui apporte instantanément volume et texture avec une finition mate. Idéale pour les cheveux fins à normaux, elle s''applique facilement sur les racines et se fond sans parfum pour un look naturel et structuré.', 132.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/stardust.webp', 'cheveux', 12, 150, true),
  ('tame-game', 'Tame Game', 'Keune', 'Tame Game est une crème luxueuse qui hydrate et adoucit les boucles tout en contrôlant les frisottis. Enrichie en panthénol, vitamine E et huile de ricin, elle protège jusqu''à 230°C/446°F. Parfumée au Citrus Meadow, elle convient à tous les types de cheveux.', 55.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/tame-game.webp', 'cheveux', 12, 151, true),
  ('keune-the-royal-tribute-hair-serum', 'The Royal Tribute Hair Serum', 'Keune', 'Un sérum capillaire luxueux et polyvalent, infusé d''un parfum inspiré de la tulipe. Le sérum Royal Tribute, enrichi en vitamine E, protège les cheveux des agressions extérieures, les lisse et les nourrit pour une brillance éclatante.', 111.562, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-the-royal-tribute-hair-serum.webp', 'cheveux', 12, 152, true),
  ('keune-tinta-color-60ml', 'Tinta Color 60ml', 'Keune', 'Forts de 100 ans de science et de 32 ans de succès de Tinta Color, nous sommes fiers de présenter Tinta Color 2023 : de nouvelles nuances, un emballage plus durable et des résultats puissants. Il est scientifiquement prouvé que Tinta Color apporte jusqu''à 75% de nutrition en plus pour les fibres. Disponible en 140 nuances — précisez la nuance souhaitée en note de commande.', 44.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-tinta-color-60ml.webp', 'cheveux', 12, 153, true),
  ('keune-tinta-developer-10-vol-1000ml', 'Tinta Developer 10 VOL 1000ml', 'Keune', 'Keune Tinta Cream Developer est le révélateur conçu pour être utilisé avec les produits Keune Tinta Color. Il offer une stabilité accrue, pour que le pourcentage de peroxyde d''hydrogène reste identique, même à temperature élevée.', 44.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-tinta-developer-10-vol-1000ml.webp', 'cheveux', 12, 154, true),
  ('keune-tinta-developer-10-vol-60ml', 'Tinta Developer 10 VOL 60ml', 'Keune', 'Keune Tinta Cream Developer est le révélateur conçu pour être utilisé avec les produits Keune Tinta Color. Il offer une stabilité accrue, pour que le pourcentage de peroxyde d''hydrogène reste identique, même à temperature élevée.', 5.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-tinta-developer-10-vol-60ml.webp', 'cheveux', 12, 155, true),
  ('keune-tinta-developer-20-vol-1000ml', 'Tinta Developer 20 VOL 1000ml', 'Keune', 'Keune Tinta Cream Developer est le révélateur conçu pour être utilisé avec les produits Keune Tinta Color . Il offer une stabilité accrue, pour que le pourcentage de peroxyde d''hydrogène reste identique, même à temperature élevée.', 44.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-tinta-developer-20-vol-1000ml.webp', 'cheveux', 12, 156, true),
  ('keune-tinta-developer-20-vol-60ml', 'Tinta Developer 20 VOL 60ml', 'Keune', 'Keune Tinta Cream Developer est le révélateur conçu pour être utilisé avec les produits Keune Tinta Color . Il offer une stabilité accrue, pour que le pourcentage de peroxyde d''hydrogène reste identique, même à temperature élevée.', 5.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-tinta-developer-20-vol-60ml.webp', 'cheveux', 12, 157, true),
  ('keune-tinta-developer-30-vol-1000ml', 'Tinta Developer 30 VOL 1000ml', 'Keune', '', 44.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-tinta-developer-30-vol-1000ml.webp', 'cheveux', 12, 158, true),
  ('keune-tinta-developer-30-vol-60ml', 'Tinta Developer 30 VOL 60ml', 'Keune', '', 5.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-tinta-developer-30-vol-60ml.webp', 'cheveux', 12, 159, true),
  ('keune-tinta-developer-40-vol-1000ml', 'Tinta Developer 40 VOL 1000ml', 'Keune', '', 44.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-tinta-developer-40-vol-1000ml.webp', 'cheveux', 12, 160, true),
  ('keune-tinta-developer-40-vol-60ml', 'Tinta Developer 40 VOL 60ml', 'Keune', '', 5.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-tinta-developer-40-vol-60ml.webp', 'cheveux', 12, 161, true),
  ('ub-after-blonde-treatment', 'UB After Blonde Treatment', 'Keune', 'Le soin After Blonde offre une solution complète pour nourrir les cheveux blonds. Il agit comme un après-shampoing enrichi de la technologie Bond Fuser, qui crée une couche protectrice et répare activement la structure extérieure des cheveux.', 88.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/ub-after-blonde-treatment.webp', 'cheveux', 12, 162, true),
  ('ultimate-blond-powder-blond', 'Ultimate Blond Powder Blond', 'Keune', 'Keune Ultimate Blonde Cream Blonde Lifting Powder offre un décolorant de haute qualité avec des résultats brillants et purs. Grâce aux protéines végétales (blé), elle protège la structure des cheveux, les rendant 50% plus résistants.', 165.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/ultimate-blond-powder-blond.webp', 'cheveux', 12, 163, true),
  ('velvet-cloud', 'Velvet Cloud', 'Keune', 'Velvet Cloud est une mousse volumisante enrichie en panthénol, protéines végétales et vitamine E. Elle nourrit, protège et booste le volume avec une protection thermique jusqu''à 230°C. Parfumée Rhubarb Bloom, elle apporte densité et légèreté aux cheveux.', 367.554, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/velvet-cloud.webp', 'cheveux', 12, 164, true),
  ('keune-care-absolute-volume-apres-shampooing-1000ml', 'Absolute Volume Après-shampooing 1000ml', 'Keune Care', 'L'' après-shampooing Care Absolute Volume booste le volume sans alourdir. Grâce à la provitamine B5 et aux protéines de blé, il renforce et nourrit vos cheveux tout en leur apportant douceur et légèreté. Résultat : une chevelure volumineuse, soyeuse et pleine de vitalité !', 159.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-absolute-volume-apres-shampooing-1000ml.webp', 'cheveux', 12, 165, true),
  ('keune-care-absolute-volume-apres-shampooing-250ml', 'Absolute Volume Après-shampooing 250ml', 'Keune Care', 'L'' après-shampooing Care Absolute Volume booste le volume sans alourdir. Grâce à la provitamine B5 et aux protéines de blé, il renforce et nourrit vos cheveux tout en leur apportant douceur et légèreté. Résultat : une chevelure volumineuse, soyeuse et pleine de vitalité !', 93.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-absolute-volume-apres-shampooing-250ml.webp', 'cheveux', 12, 166, true),
  ('keune-care-absolute-volume-shampooing-1000ml', 'Absolute Volume Shampooing 1000ml', 'Keune Care', 'Le shampooing Care Absolute Volume donne du corps aux cheveux fins. Grâce à la provitamine B5 et aux protéines de blé, il renforce la fibre capillaire sans l''alourdir. Résultat : des cheveux plus volumineux, légers et pleins de vitalité en un instant !', 154.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-absolute-volume-shampooing-1000ml.webp', 'cheveux', 12, 167, true),
  ('keune-care-absolute-volume-shampooing-300ml', 'Absolute Volume Shampooing 300ml', 'Keune Care', 'Le shampooing Care Absolute Volume donne du corps aux cheveux fins. Grâce à la provitamine B5 et aux protéines de blé, il renforce la fibre capillaire sans l''alourdir. Résultat : des cheveux plus volumineux, légers et pleins de vitalité en un instant !', 88.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-absolute-volume-shampooing-300ml.webp', 'cheveux', 12, 168, true),
  ('care-absolute-volume-thermal-protector', 'Absolute Volume Thermal Protector', 'Keune Care', 'La chaleur des outils de coiffage peut fragiliser vos cheveux. Care Absolute Volume Thermal Protector les protège efficacement grâce à la provitamine B5 et aux protéines de blé. Il préserve l''hydratation, empêche le dessèchement et maintient vos cheveux doux, sains et volumineux.', 93.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/care-absolute-volume-thermal-protector.webp', 'cheveux', 12, 169, true),
  ('care-blonde-savior-leave-in-treatment', 'Blonde Savior Leave-in Treatment', 'Keune Care', 'Les cheveux décolorés peuvent être restaurés avec Care Blonde Savior . Ce soin sans rinçage, enrichi en acide glycolique et créatine, renforce et nourrit en profondeur. Il protège aussi de la chaleur, laissant vos cheveux coiffés, bouclés ou séchés doux, sains et brillants.', 93.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/care-blonde-savior-leave-in-treatment.webp', 'cheveux', 12, 170, true),
  ('keune-care-blonde-savior-masque-200ml', 'Blonde Savior Masque 200ml', 'Keune Care', 'Les cheveux abîmés par la décoloration peuvent être réparés. Care Blonde Savior renforce et protège grâce à la créatine et au Keravis, réduisant la casse. Enrichi en Mirasil, il nourrit en profondeur, laissant vos cheveux blonds plus sains, brillants, doux et soyeux.', 93.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-blonde-savior-masque-200ml.webp', 'cheveux', 12, 171, true),
  ('keune-care-blonde-savior-masque-500ml', 'Blonde Savior Masque 500ml', 'Keune Care', 'Les cheveux abîmés par la décoloration peuvent être réparés. Care Blonde Savior renforce et protège grâce à la créatine et au Keravis, réduisant la casse. Enrichi en Mirasil, il nourrit en profondeur, laissant vos cheveux blonds plus sains, brillants, doux et soyeux.', 132.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-blonde-savior-masque-500ml.webp', 'cheveux', 12, 172, true),
  ('keune-care-blonde-savior-shampooing-1000ml', 'Blonde Savior Shampooing 1000ml', 'Keune Care', 'Cheveux abîmés par une décoloration ? Care Blonde Savior répare en profondeur sans sulfate, offrant douceur et nutrition. Conçu pour les cheveux éclaircis, il réduit la casse et facilite le coiffage. Après usage régulier, retrouvez des cheveux forts, soyeux et revitalisés.', 154.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-blonde-savior-shampooing-1000ml.webp', 'cheveux', 12, 173, true),
  ('keune-care-blonde-savior-shampooing-300ml', 'Blonde Savior Shampooing 300ml', 'Keune Care', 'Cheveux abîmés par une décoloration ? Care Blonde Savior répare en profondeur sans sulfate, offrant douceur et nutrition. Conçu pour les cheveux éclaircis, il réduit la casse et facilite le coiffage. Après usage régulier, retrouvez des cheveux forts, soyeux et revitalisés.', 88.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-blonde-savior-shampooing-300ml.webp', 'cheveux', 12, 174, true),
  ('keune-care-color-brillianz-apres-shampooing-1000ml', 'Color Brillianz Après-shampooing 1000ml', 'Keune Care', 'Protégez l''éclat de votre couleur avec Care Color Brillianz Conditioner . Son Color Sealing Complex préserve les pigments et bloque les UV, évitant l''affadissement. Enrichi en protéines de soie, il hydrate et apporte brillance, laissant vos cheveux colorés doux, lumineux et en pleine santé.', 159.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-color-brillianz-apres-shampooing-1000ml.webp', 'cheveux', 12, 175, true),
  ('keune-care-color-brillianz-apres-shampooing-250ml', 'Color Brillianz Après-shampooing 250ml', 'Keune Care', 'Protégez l''éclat de votre couleur avec Care Color Brillianz Conditioner . Son Color Sealing Complex préserve les pigments et bloque les UV, évitant l''affadissement. Enrichi en protéines de soie, il hydrate et apporte brillance, laissant vos cheveux colorés doux, lumineux et en pleine santé.', 93.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-color-brillianz-apres-shampooing-250ml.webp', 'cheveux', 0, 176, true),
  ('keune-care-color-brillianz-masque-200ml', 'Color Brillianz Masque 200ml', 'Keune Care', 'Offrez un soin intense à vos cheveux colorés avec Care Color Brillianz Mask . Il nourrit, renforce l''éclat et prolonge la couleur grâce au Color Sealing Complex , aux protéines de soie et à la protection UV. Résultat : des cheveux doux, brillants et protégés.', 93.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-color-brillianz-masque-200ml.webp', 'cheveux', 12, 177, true),
  ('keune-care-color-brillianz-masque-500ml', 'Color Brillianz Masque 500ml', 'Keune Care', 'Offrez un soin intense à vos cheveux colorés avec Care Color Brillianz Mask . Il nourrit, renforce l''éclat et prolonge la couleur grâce au Color Sealing Complex , aux protéines de soie et à la protection UV. Résultat : des cheveux doux, brillants et protégés.', 132.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-color-brillianz-masque-500ml.webp', 'cheveux', 12, 178, true),
  ('keune-care-color-brillianz-shampooing-1000ml', 'Color Brillianz Shampooing 1000ml', 'Keune Care', 'Préservez l''éclat de votre couleur avec Care Color Brillianz Shampoo . Son Color Sealing Complex protège les pigments, prolongeant l''intensité. Enrichi en protéines de soie et filtre UV, il nourrit, hydrate et prévient l''affadissement, laissant vos cheveux colorés brillants, doux et en pleine santé.', 154.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-color-brillianz-shampooing-1000ml.webp', 'cheveux', 12, 179, true),
  ('keune-care-color-brillianz-shampooing-300ml', 'Color Brillianz Shampooing 300ml', 'Keune Care', 'Préservez l''éclat de votre couleur avec Care Color Brillianz Shampoo . Son Color Sealing Complex protège les pigments, prolongeant l''intensité. Enrichi en protéines de soie et filtre UV, il nourrit, hydrate et prévient l''affadissement, laissant vos cheveux colorés brillants, doux et en pleine santé.', 88.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-color-brillianz-shampooing-300ml.webp', 'cheveux', 12, 180, true),
  ('care-color-brillianz-spray-conditionneur', 'Color Brillianz Spray Conditionneur', 'Keune Care', 'Offrez à vos cheveux colorés un boost d''hydratation avec Care Color Brillianz Spray Conditionneur. Léger et nourrissant, il protège la couleur avec le Color Sealing Complex, apporte éclat grâce aux protéines de soie et bloque les UV pour une tenue prolongée.', 88.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/care-color-brillianz-spray-conditionneur.webp', 'cheveux', 12, 181, true),
  ('care-confident-curl-low-poo-shampooing', 'Confident Curl Low-Poo Shampooing', 'Keune Care', 'Ce shampooing sans sulfate nettoie en douceur les cheveux bouclés tout en préservant leur hydratation. Enrichi en huile de coco pour renforcer les boucles et en extrait de vinaigre pour équilibrer le pH, il réduit les frisottis et définit les boucles.', 88.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/care-confident-curl-low-poo-shampooing.webp', 'cheveux', 12, 182, true),
  ('care-confident-curl-masque', 'Confident Curl Masque', 'Keune Care', 'Découvrez le masque Confident Curl, une formule révolutionnaire pour des cheveux lisses et sans frisottis. Enrichi en beurre de karité, huile de coco et extrait de vinaigre, il hydrate, protège et définit les boucles pour une chevelure éclatante et saine.', 93.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/care-confident-curl-masque.webp', 'cheveux', 12, 183, true),
  ('care-derma-activate-lotion', 'Derma Activate Lotion', 'Keune Care', 'Freinez la chute des cheveux avec Care Derma Activate Lotion ! Enrichie en biotine, caféine et takanal, cette lotion active la régénération du cuir chevelu, prolonge la croissance des cheveux et réduit leur chute. Des cheveux plus forts, plus épais, plus longtemps.', 99.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/care-derma-activate-lotion.webp', 'cheveux', 12, 184, true),
  ('keune-care-derma-activate-shampooing-1000ml', 'Derma Activate Shampooing 1000ml', 'Keune Care', 'Redonnez vie à vos cheveux ! Care Derma Activate Shampoo stimule le métabolisme du cuir chevelu pour prévenir la chute des cheveux. Grâce à la vitamine H, il renforce la kératine, rendant vos cheveux plus épais, plus forts et visiblement plus volumineux.', 154.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-derma-activate-shampooing-1000ml.webp', 'cheveux', 12, 185, true),
  ('keune-care-derma-activate-shampooing-300ml', 'Derma Activate Shampooing 300ml', 'Keune Care', 'Redonnez vie à vos cheveux ! Care Derma Activate Shampoo stimule le métabolisme du cuir chevelu pour prévenir la chute des cheveux. Grâce à la vitamine H, il renforce la kératine, rendant vos cheveux plus épais, plus forts et visiblement plus volumineux.', 88.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-derma-activate-shampooing-300ml.webp', 'cheveux', 12, 186, true),
  ('care-derma-activate-thickening-spray', 'Derma Activate Thickening Spray', 'Keune Care', 'Obtenez des cheveux plus denses avec le Spray épaississant Care Derma Activate ! Ce spray sans rinçage renforce la kératine grâce à la vitamine H , réduisant ainsi la chute des cheveux. Enrichi en provitamine B5 , il hydrate et épaissit durablement la fibre capillaire.', 88.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/care-derma-activate-thickening-spray.webp', 'cheveux', 12, 187, true),
  ('keune-care-derma-exfoliate-shampooing-1000ml', 'Derma Exfoliate Shampooing 1000ml', 'Keune Care', 'Le shampooing Care Derma Exfoliate rééquilibre votre cuir chevelu et réduit les pellicules en douceur. Enrichi en octopirox, il combat la prolifération des micro-organismes responsables des pellicules tout en apaisant les démangeaisons. Résultat : un cuir chevelu sain et des cheveux éclatants.', 154.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-derma-exfoliate-shampooing-1000ml.webp', 'cheveux', 12, 188, true),
  ('keune-care-derma-exfoliate-shampooing-300ml', 'Derma Exfoliate Shampooing 300ml', 'Keune Care', 'Le shampooing Care Derma Exfoliate rééquilibre votre cuir chevelu et réduit les pellicules en douceur. Enrichi en octopirox, il combat la prolifération des micro-organismes responsables des pellicules tout en apaisant les démangeaisons. Résultat : un cuir chevelu sain et des cheveux éclatants.', 88.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-derma-exfoliate-shampooing-300ml.webp', 'cheveux', 12, 189, true),
  ('keune-care-derma-regulate-shampooing-1000ml', 'Derma Regulate Shampooing 1000ml', 'Keune Care', 'Le shampooing Care Derma Regulate équilibre la production de sébum grâce à son complexe bio-soufre et bétaïne. Il purifie sans agresser, laissant vos cheveux doux et frais. Idéal pour un cuir chevelu sain et une sensation de légèreté durable.', 154.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-derma-regulate-shampooing-1000ml.webp', 'cheveux', 12, 190, true),
  ('keune-care-derma-regulate-shampooing-300ml', 'Derma Regulate Shampooing 300ml', 'Keune Care', 'Le shampooing Care Derma Regulate équilibre la production de sébum grâce à son complexe bio-soufre et bétaïne. Il purifie sans agresser, laissant vos cheveux doux et frais. Idéal pour un cuir chevelu sain et une sensation de légèreté durable.', 88.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-derma-regulate-shampooing-300ml.webp', 'cheveux', 12, 191, true),
  ('keune-care-derma-regulate-shampooing-nouveau-packaging-1000ml', 'Derma Regulate Shampooing | Nouveau packaging 1000ml', 'Keune Care', 'Le shampooing Care Derma Regulate équilibre la production de sébum grâce à son complexe bio-soufre et bétaïne. Il purifie sans agresser, laissant vos cheveux doux et frais. Idéal pour un cuir chevelu sain et une sensation de légèreté durable.', 154.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-derma-regulate-shampooing-nouveau-packaging-1000ml.webp', 'cheveux', 0, 192, true),
  ('keune-care-derma-regulate-shampooing-nouveau-packaging-300ml', 'Derma Regulate Shampooing | Nouveau packaging 300ml', 'Keune Care', 'Le shampooing Care Derma Regulate équilibre la production de sébum grâce à son complexe bio-soufre et bétaïne. Il purifie sans agresser, laissant vos cheveux doux et frais. Idéal pour un cuir chevelu sain et une sensation de légèreté durable.', 88.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-derma-regulate-shampooing-nouveau-packaging-300ml.webp', 'cheveux', 0, 193, true),
  ('care-derma-sensitive-lotion', 'Derma Sensitive Lotion', 'Keune Care', 'La lotion Care Derma Sensitive apaise immédiatement le cuir chevelu irrité ou sensible. Sans sulfates ni colorants et avec un parfum pauvre en allergènes, elle réduit rougeurs, démangeaisons et irritations, aidant votre cuir chevelu à se rééquilibrer et à retrouver son confort naturel.', 99.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/care-derma-sensitive-lotion.webp', 'cheveux', 12, 194, true),
  ('keune-care-derma-sensitive-masque-200ml', 'Derma Sensitive Masque 200ml', 'Keune Care', 'Le masque Care Derma Sensitive hydrate en profondeur le cuir chevelu sec, réduisant les démangeaisons et irritations. Sa formule dermatologiquement approuvée restaure l''équilibre hydrique, offrant un soin apaisant et nourrissant immédiat pour un cuir chevelu confortable et des cheveux en pleine santé.', 93.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-derma-sensitive-masque-200ml.webp', 'cheveux', 12, 195, true),
  ('keune-care-derma-sensitive-masque-500ml', 'Derma Sensitive Masque 500ml', 'Keune Care', 'Le masque Care Derma Sensitive hydrate en profondeur le cuir chevelu sec, réduisant les démangeaisons et irritations. Sa formule dermatologiquement approuvée restaure l''équilibre hydrique, offrant un soin apaisant et nourrissant immédiat pour un cuir chevelu confortable et des cheveux en pleine santé.', 132.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-derma-sensitive-masque-500ml.webp', 'cheveux', 12, 196, true),
  ('care-derma-sensitive-shampooing', 'Derma Sensitive Shampooing', 'Keune Care', 'Le shampooing Care Derma Sensitive apaise le cuir chevelu grâce au Scalp Soothing Complex . Sans sulfates, alcool ni colorants, il réduit les démangeaisons et hydrate en douceur. Son parfum hypoallergénique garantit confort et soin pour des cheveux doux et sains.', 88.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/care-derma-sensitive-shampooing.webp', 'cheveux', 12, 197, true),
  ('care-keratin-smooth-2-phase-spray', 'Keratin Smooth 2 Phase Spray', 'Keune Care', 'Le spray sans rinçage Care Keratin Smooth 2-Phase facilite le démêlage et prévient les nœuds sans alourdir les cheveux. Grâce à son pH faible, il agit immédiatement, laissant les cheveux plus lisses, brillants et faciles à coiffer.', 49.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/care-keratin-smooth-2-phase-spray.webp', 'cheveux', 12, 198, true),
  ('keune-care-keratin-smooth-apres-shampooing-1000ml', 'Keratin Smooth Après-shampooing 1000ml', 'Keune Care', 'Des cheveux lisses et disciplinés, sans frisottis ! L''après-shampooing Care Keratin Smooth renforce vos cheveux de l''intérieur grâce à la kératine et à la Provitamine B5, qui optimise leur hydratation. Son complexe Quat protège contre la casse, idéal pour cheveux secs et abîmés.', 159.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-keratin-smooth-apres-shampooing-1000ml.webp', 'cheveux', 12, 199, true),
  ('keune-care-keratin-smooth-apres-shampooing-250ml', 'Keratin Smooth Après-shampooing 250ml', 'Keune Care', 'Des cheveux lisses et disciplinés, sans frisottis ! L''après-shampooing Care Keratin Smooth renforce vos cheveux de l''intérieur grâce à la kératine et à la Provitamine B5, qui optimise leur hydratation. Son complexe Quat protège contre la casse, idéal pour cheveux secs et abîmés.', 93.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-keratin-smooth-apres-shampooing-250ml.webp', 'cheveux', 12, 200, true),
  ('keune-care-keratin-smooth-masque-200ml', 'Keratin Smooth Masque 200ml', 'Keune Care', 'Vos cheveux sont frisés ou abîmés ? Le masque Care Keratin Smooth, enrichi en kératine, peptides et Keravis, renforce et répare la fibre capillaire. Il réduit la casse et les frisottis tout en protégeant vos cheveux pour une apparence plus lisse et saine.', 93.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-keratin-smooth-masque-200ml.webp', 'cheveux', 12, 201, true),
  ('keune-care-keratin-smooth-masque-500ml', 'Keratin Smooth Masque 500ml', 'Keune Care', 'Vos cheveux sont frisés ou abîmés ? Le masque Care Keratin Smooth, enrichi en kératine, peptides et Keravis, renforce et répare la fibre capillaire. Il réduit la casse et les frisottis tout en protégeant vos cheveux pour une apparence plus lisse et saine.', 132.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-keratin-smooth-masque-500ml.webp', 'cheveux', 12, 202, true),
  ('care-keratin-smooth-serum', 'Keratin Smooth Serum', 'Keune Care', 'Si vous utilisez souvent des outils chauffants, le sérum Care Keratin Smooth protège vos cheveux de la chaleur. Enrichi en kératine, huile d''argan et minéraux nourrissants, il renforce la fibre capillaire, réduit les frisottis et préserve l''hydratation pour des cheveux plus sains.', 0.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/care-keratin-smooth-serum.webp', 'cheveux', 12, 203, false),
  ('keune-care-keratin-smooth-shampooing-1000ml', 'Keratin Smooth Shampooing 1000ml', 'Keune Care', 'Dites adieu aux frisottis et aux cheveux statiques ! Le shampooing Care Keratin Smooth, enrichi en kératine, nourrit vos cheveux en profondeur pour une douceur irrésistible. Son complexe Quat renforce et protège contre la casse, idéal pour les cheveux secs ou abîmés.', 154.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-keratin-smooth-shampooing-1000ml.webp', 'cheveux', 12, 204, true),
  ('keune-care-keratin-smooth-shampooing-300ml', 'Keratin Smooth Shampooing 300ml', 'Keune Care', 'Dites adieu aux frisottis et aux cheveux statiques ! Le shampooing Care Keratin Smooth, enrichi en kératine, nourrit vos cheveux en profondeur pour une douceur irrésistible. Son complexe Quat renforce et protège contre la casse, idéal pour les cheveux secs ou abîmés.', 88.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-keratin-smooth-shampooing-300ml.webp', 'cheveux', 12, 205, true),
  ('keune-care-lumi-coat-luminous-shine-spray', 'Lumi Coat Luminous Shine Spray', 'Keune Care', 'Le spray Care Lumi Coat apporte brillance et douceur aux cheveux abîmés grâce à la technologie Fiber Sealing. Il lisse la cuticule, protège chaque mèche et crée un fini soyeux tout en renforçant la fibre capillaire.', 93.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-lumi-coat-luminous-shine-spray.webp', 'cheveux', 12, 206, true),
  ('care-lumi-coat-supreme-cream', 'Lumi Coat Supreme Cream', 'Keune Care', 'Care Lumi Coat Luminous Supreme Cream nourrit et protège les cheveux secs ou abîmés grâce à la technologie Fiber Sealing. Elle forme une barrière protectrice, prévient les dommages, réduit les frisottis et apporte une brillance éclatante pour des cheveux plus lisses et disciplinés.', 110.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/care-lumi-coat-supreme-cream.webp', 'cheveux', 12, 207, true),
  ('keune-care-miracle-elixir-spray-de-keratine', 'Miracle Elixir Spray De Kératine', 'Keune Care', 'Vous avez reçu un traitement Miracle Elixir en salon ? Care Miracle Elixir Keratin Spray vous aide à maintenant ce résultat. Même après 5 lavages, vos cheveux resteront beaux et doux grâce à l''élixir de kératine contenu dans ce spray.', 93.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-miracle-elixir-spray-de-keratine.webp', 'cheveux', 12, 208, true),
  ('keune-care-satin-oil-apres-shampooing-1000ml', 'Satin Oil Après-shampooing 1000ml', 'Keune Care', 'L''huile hydrate sans alourdir, apportant brillance et santé aux cheveux. L''après-shampooing Care Satin Oil nourrit en profondeur avec des huiles de maracuja, baobab et monoï, offrant une hydratation intense aux cheveux secs pour une douceur éclatante et soyeuse.', 159.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-satin-oil-apres-shampooing-1000ml.webp', 'cheveux', 12, 209, true),
  ('keune-care-satin-oil-apres-shampooing-250ml', 'Satin Oil Après-shampooing 250ml', 'Keune Care', 'L''huile hydrate sans alourdir, apportant brillance et santé aux cheveux. L''après-shampooing Care Satin Oil nourrit en profondeur avec des huiles de maracuja, baobab et monoï, offrant une hydratation intense aux cheveux secs pour une douceur éclatante et soyeuse.', 93.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-satin-oil-apres-shampooing-250ml.webp', 'cheveux', 12, 210, true),
  ('keune-care-satin-oil-masque-250ml', 'Satin Oil Masque 250ml', 'Keune Care', 'Parfois, il suffit d''un petit plus pour faire briller les cheveux ternes. Un masque capillaire apporte cette touche supplémentaire. Le masque Care Satin Oil contient un mélange d''huiles de maracuja, de baobab et de monoï et 5 minéraux nourrissants. Les cheveux restent ainsi doux et sains.', 93.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-satin-oil-masque-250ml.webp', 'cheveux', 12, 211, true),
  ('keune-care-satin-oil-masque-95ml', 'Satin Oil Masque 95ml', 'Keune Care', 'Parfois, il suffit d''un petit plus pour faire briller les cheveux ternes. Un masque capillaire apporte cette touche supplémentaire. Le masque Care Satin Oil contient un mélange d''huiles de maracuja, de baobab et de monoï et 5 minéraux nourrissants. Les cheveux restent ainsi doux et sains.', 88.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-satin-oil-masque-95ml.webp', 'cheveux', 12, 212, true),
  ('keune-care-satin-oil-shampooing-1000ml', 'Satin Oil Shampooing 1000ml', 'Keune Care', 'Saviez-vous que l''huile ne rend pas nécessairement vos cheveux gras ou lourds ? Au contraire, elle donne brillance et hydratation. Le shampooing Care Satin Oil contient un trio d''huiles en or pour cela : les huiles de maracuja, de baobab et de monoï qui rendent vos cheveux brillants et doux comme de la soie.', 154.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-satin-oil-shampooing-1000ml.webp', 'cheveux', 12, 213, true),
  ('keune-care-satin-oil-shampooing-300ml', 'Satin Oil Shampooing 300ml', 'Keune Care', 'Saviez-vous que l''huile ne rend pas nécessairement vos cheveux gras ou lourds ? Au contraire, elle donne brillance et hydratation. Le shampooing Care Satin Oil contient un trio d''huiles en or pour cela : les huiles de maracuja, de baobab et de monoï qui rendent vos cheveux brillants et doux comme de la soie.', 88.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-satin-oil-shampooing-300ml.webp', 'cheveux', 12, 214, true),
  ('care-satin-oil-huile-de-soin', 'Satin Oil – Huile De Soin', 'Keune Care', 'Un traitement à l''huile n''alourdit pas les cheveux, il les hydrate et les fait briller. Care Satin Oil Treatment, enrichi en huiles de maracuja, baobab et monoï, nourrit intensément. Quelques gouttes suffisent pour des cheveux doux, lumineux et soyeux.', 132.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/care-satin-oil-huile-de-soin.webp', 'cheveux', 12, 215, true),
  ('care-satin-oil-oil-milk', 'Satin Oil – Oil Milk', 'Keune Care', 'Ce spray riche est si léger qu''il est instantanément absorbé par les cheveux. Sa formule ultralégère optimise l''hydratation des cheveux, sans les rendre gras. Ce produit permet d''obtenir une chevelure merveilleusement douce et brillante.', 88.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/care-satin-oil-oil-milk.jpg', 'cheveux', 12, 216, true),
  ('keune-care-silver-savior-apres-shampooing-1000ml', 'Silver Savior Après-shampooing 1000ml', 'Keune Care', 'L''après-shampooing Care Silver Savior neutralise les reflets jaunes des cheveux argentés ou décolorés grâce à ses pigments violets. Enrichi en provitamine B5, protéines nourrissantes et technologie Bond Fuser, il hydrate, renforce et sublime la brillance de votre couleur.', 159.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-silver-savior-apres-shampooing-1000ml.webp', 'cheveux', 12, 217, true),
  ('keune-care-silver-savior-apres-shampooing-250ml', 'Silver Savior Après-shampooing 250ml', 'Keune Care', 'L''après-shampooing Care Silver Savior neutralise les reflets jaunes des cheveux argentés ou décolorés grâce à ses pigments violets. Enrichi en provitamine B5, protéines nourrissantes et technologie Bond Fuser, il hydrate, renforce et sublime la brillance de votre couleur.', 93.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-silver-savior-apres-shampooing-250ml.webp', 'cheveux', 12, 218, true),
  ('keune-care-silver-savior-shampooing-1000ml', 'Silver Savior Shampooing 1000ml', 'Keune Care', 'Le shampooing Care Silver Savior neutralise les reflets jaunes des cheveux blonds, gris ou argentés grâce à ses pigments violets. Enrichi en provitamine B5 et protéines de blé, il renforce, hydrate et protège la structure capillaire pour une couleur éclatante.', 154.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-silver-savior-shampooing-1000ml.webp', 'cheveux', 12, 219, true),
  ('keune-care-silver-savior-shampooing-300ml', 'Silver Savior Shampooing 300ml', 'Keune Care', 'Le shampooing Care Silver Savior neutralise les reflets jaunes des cheveux blonds, gris ou argentés grâce à ses pigments violets. Enrichi en provitamine B5 et protéines de blé, il renforce, hydrate et protège la structure capillaire pour une couleur éclatante.', 88.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-silver-savior-shampooing-300ml.webp', 'cheveux', 12, 220, true),
  ('care-sun-shield-apres-shampooing', 'Sun Shield Après-shampooing', 'Keune Care', 'L''après-shampooing Sun Shield, enrichi en beurre de karité, hydrate et répare les cheveux exposés au soleil. Ses polymères cationiques et quats lissent et facilitent le coiffage. Grâce à son filtre UV, il protège des rayons nocifs pour des cheveux éclatants tout l''été.', 93.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/care-sun-shield-apres-shampooing.jpg', 'cheveux', 12, 221, true),
  ('keune-care-sun-shield-oil', 'Sun Shield Oil', 'Keune Care', 'Glissez cette huile de protection solaire dans votre sac de plage. Avec un FPS 8, elle protège et hydrate vos cheveux. Sa formule légère enveloppe chaque mèche pour prévenir la déshydratation, tout en bloquant les rayons UVA et UVB pour préserver votre couleur.', 82.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-sun-shield-oil.png', 'cheveux', 12, 222, true),
  ('care-sun-shield-shampooing', 'Sun Shield Shampooing', 'Keune Care', 'Le shampooing Sun Shield élimine en douceur les résidus de crème solaire, chlore et sel après l''été. Enrichi en minéraux essentiels et provitamine B5, il nourrit et hydrate les cheveux, les rendant doux, brillants et revitalisés après l''exposition au soleil.', 88.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/care-sun-shield-shampooing.jpg', 'cheveux', 12, 223, true),
  ('care-tinta-color-apres-shampooing', 'Tinta Color Après-shampooing', 'Keune Care', 'Vous souhiatez que votre couleur reste éclatante longtemps à la maison ? L''après-shampooing Care Tinta Color vous y aide. Il contient certains des mêmes ingrédients que nos produits Tinta en salon et est parfait pour une utilisation à la maison post-coloration.', 93.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/care-tinta-color-apres-shampooing.webp', 'cheveux', 12, 224, true),
  ('keune-care-tinta-color-shampooing-250ml', 'Tinta Color Shampooing 250ml', 'Keune Care', 'Faites durer l''éclat de votre couleur avec Care Tinta Color Shampoo . Enrichi en protéines de soie, LP300 et filtre UV, il protège les pigments et nourrit sans sulfate. Vos cheveux colorés restent lumineux, doux et éclatants plus longtemps.', 88.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-tinta-color-shampooing-250ml.webp', 'cheveux', 12, 225, true),
  ('keune-care-tinta-color-shampooing-300ml', 'Tinta Color Shampooing 300ml', 'Keune Care', 'Faites durer l''éclat de votre couleur avec Care Tinta Color Shampoo . Enrichi en protéines de soie, LP300 et filtre UV, il protège les pigments et nourrit sans sulfate. Vos cheveux colorés restent lumineux, doux et éclatants plus longtemps.', 93.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-tinta-color-shampooing-300ml.webp', 'cheveux', 12, 226, true),
  ('keune-care-vital-nutrition-apres-shampooing-1000ml', 'Vital Nutrition Après-shampooing 1000ml', 'Keune Care', 'Tous les cheveux ont besoin d''hydratation pour rester en bonne santé. Care Vital Nutrition Conditioner nourrit en profondeur avec de la provitamine B5 et du beurre de karité, réparant et redonnant brillance aux cheveux abîmés. Une solution complète pour des cheveux doux et revitalisés.', 159.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-care-vital-nutrition-apres-shampooing-1000ml.webp', 'cheveux', 12, 227, true),
