  ('care-vital-nutrition-porosity-filler', 'Vital Nutrition Porosity Filler', 'Keune Care', 'Cheveux secs ou abîmés ? Care Vital Nutrition Porosity Filler renforce et répare en profondeur. Grâce à la céramide et aux protéines de blé, il restaure la fibre capillaire de l''intérieur et l''extérieur, redonnant force, douceur et vitalité à vos cheveux.', 87.307, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/care-vital-nutrition-porosity-filler.webp', 'cheveux', 12, 231, true),
  ('care-vital-nutrition-protein-spray', 'Vital Nutrition Protein Spray', 'Keune Care', 'Cheveux secs ou cassants ? Care Vital Nutrition Protein Spray hydrate, renforce et apporte de la brillance. Idéal avant et après une coloration ou l''usage d''outils chauffants, il protège et facilite le coiffage pour des cheveux plus doux, souples et éclatants.', 88.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/care-vital-nutrition-protein-spray.webp', 'cheveux', 12, 232, true),
