  ('keune-so-pure-cool-apres-shampooing-eco-recharge-1000ml', 'Cool Après-shampooing Eco-recharge 1000ml', 'Keune So Pure', 'So Pure Cool – Le shampoing argenté qui neutralise les reflets cuivrés grâce à ses puissants pigments violets . Enrichi en extrait de baies d''açaï , il protège les cheveux de l''oxydation et préserve l''éclat de la couleur. Résultat : des cheveux hydratés, doux et subtilement glacés .', 181.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-so-pure-cool-apres-shampooing-eco-recharge-1000ml.webp', 'cheveux', 12, 252, true),
  ('keune-so-pure-cool-apres-shampooing-eco-recharge-400ml', 'Cool Après-shampooing Eco-recharge 400ml', 'Keune So Pure', 'So Pure Cool – Le shampoing argenté qui neutralise les reflets cuivrés grâce à ses puissants pigments violets . Enrichi en extrait de baies d''açaï , il protège les cheveux de l''oxydation et préserve l''éclat de la couleur. Résultat : des cheveux hydratés, doux et subtilement glacés .', 104.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-so-pure-cool-apres-shampooing-eco-recharge-400ml.webp', 'cheveux', 12, 253, true),
  ('keune-so-pure-cool-shampooing-eco-recharge-1000ml', 'Cool Shampooing Eco-recharge 1000ml', 'Keune So Pure', 'So Pure Cool neutralise les tons cuivrés avec des pigments violets puissants. Enrichi en baies d''açaï, il protège contre l''oxydation et hydrate les cheveux, laissant une lueur glacée. Lauréat du Dutch Beauty Award 2023-2024.', 176.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-so-pure-cool-shampooing-eco-recharge-1000ml.webp', 'cheveux', 12, 254, true),
  ('keune-so-pure-cool-shampooing-eco-recharge-400ml', 'Cool Shampooing Eco-recharge 400ml', 'Keune So Pure', 'So Pure Cool neutralise les tons cuivrés avec des pigments violets puissants. Enrichi en baies d''açaï, il protège contre l''oxydation et hydrate les cheveux, laissant une lueur glacée. Lauréat du Dutch Beauty Award 2023-2024.', 99.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-so-pure-cool-shampooing-eco-recharge-400ml.webp', 'cheveux', 12, 255, true),
  ('so-pure-cooling-elixir', 'Cooling ELIXIR', 'Keune So Pure', 'So Pure Cooling Elixir : rafraîchissement et bien-être Profitez de l''intensité rafraîchissante du Cooling Elixir sans rinçage. Grâce à menthe poivrée, romarin et huile d''argan bio , il stimule la circulation du cuir chevelu, nourrit et hydrate en profondeur pour des cheveux frais et sains toute la journée.', 66.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/so-pure-cooling-elixir.webp', 'cheveux', 12, 256, true),
  ('so-pure-energizing-essential-oil', 'Energizing Essential Oil', 'Keune So Pure', 'Energizing Essential Oil renforce les cheveux fins, favorise la croissance et prévient la chute. Grâce aux huiles essentielles de gingembre et citron , elle offre un parfum frais. Sans parabens ni sulfates, pour des cheveux revitalisés et une sensation de fraîcheur.', 66.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/so-pure-energizing-essential-oil.webp', 'cheveux', 12, 257, true),
  ('so-pure-energizing-lotion', 'Energizing Lotion', 'Keune So Pure', 'Les hommes et les femmes des laboratoires Keune savent de quoi ils parlent, surtout quand il s''agit de faire pousser des cheveux plus sains. La So Pure Energizing Lotion est une lotion de croissance capillaire sans rinçage, exploitant toute la puissance de la nature.', 99.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/so-pure-energizing-lotion.webp', 'cheveux', 12, 258, true),
  ('keune-so-pure-energizing-shampoo-1000ml', 'Energizing Shampoo 1000ml', 'Keune So Pure', 'So Pure Energizing Shampoo : boostez la croissance de vos cheveux 🌿 Ce shampooing doux, enrichi en gingembre , citron , ginseng rouge , et biotine , stimule la circulation et prévient la chute des cheveux.', 165.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-so-pure-energizing-shampoo-1000ml.webp', 'cheveux', 12, 259, true),
