  ('so-pure-moroccan-argan-oil-light', 'Moroccan Argan Oil Light', 'Keune So Pure', 'Cette charmante huile capillaire de la marque Keune est idéale pour les cheveux cassants et fins et lui confère une brillance exceptionnelle sans les alourdir.', 60.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/so-pure-moroccan-argan-oil-light.webp', 'cheveux', 12, 269, true),
