  ('so-pure-recover-treatment', 'Recover Treatment', 'Keune So Pure', '', 88.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/so-pure-recover-treatment.webp', 'cheveux', 12, 278, true),
  ('keune-so-pure-restore-apres-shampooing-eco-recharge-1000ml', 'Restore Après-shampooing Eco-recharge 1000ml', 'Keune So Pure', 'So Pure Restore hydrate et nourrit les cheveux secs et abîmés. L''extrait de figue de barbarie nourrit en profondeur, rendant les cheveux plus sains et légers. Appliquez, laissez agir 1 à 3 minutes, puis rincez abondamment. La gamme a remporté le Dutch Beauty Award 2023-2024.', 181.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-so-pure-restore-apres-shampooing-eco-recharge-1000ml.webp', 'cheveux', 12, 279, true),
  ('keune-so-pure-restore-apres-shampooing-eco-recharge-400ml', 'Restore Après-shampooing Eco-recharge 400ml', 'Keune So Pure', 'So Pure Restore hydrate et nourrit les cheveux secs et abîmés. L''extrait de figue de barbarie nourrit en profondeur, rendant les cheveux plus sains et légers. Appliquez, laissez agir 1 à 3 minutes, puis rincez abondamment. La gamme a remporté le Dutch Beauty Award 2023-2024.', 104.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-so-pure-restore-apres-shampooing-eco-recharge-400ml.webp', 'cheveux', 12, 280, true),
  ('so-pure-restore-masque', 'Restore Masque', 'Keune So Pure', 'Hydrate intensément chaque mèche grâce à l''extrait de figue de barbarie. Sa formule riche nourrit en profondeur pour des cheveux plus sains et hydratés. Appliquez, laissez agir 3 minutes, puis rincez abondamment.', 99.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/so-pure-restore-masque.webp', 'cheveux', 12, 281, true),
  ('keune-so-pure-restore-shampooing-eco-recharge-1000ml', 'Restore Shampooing Eco-recharge 1000ml', 'Keune So Pure', 'So Pure Restore hydrate et revitalise les cheveux secs et abîmés grâce à l''extrait de figue de barbarie. Il nettoie délicatement, offrant des cheveux sains et légers. Massez sur cheveux mouillés, laissez agir, puis rincez abondamment. La gamme a remporté le Dutch Beauty Award 2023-2024.', 176.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-so-pure-restore-shampooing-eco-recharge-1000ml.webp', 'cheveux', 12, 282, true),
  ('keune-so-pure-restore-shampooing-eco-recharge-400ml', 'Restore Shampooing Eco-recharge 400ml', 'Keune So Pure', 'So Pure Restore hydrate et revitalise les cheveux secs et abîmés grâce à l''extrait de figue de barbarie. Il nettoie délicatement, offrant des cheveux sains et légers. Massez sur cheveux mouillés, laissez agir, puis rincez abondamment. La gamme a remporté le Dutch Beauty Award 2023-2024.', 99.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/keune-so-pure-restore-shampooing-eco-recharge-400ml.webp', 'cheveux', 12, 283, true),
  ('so-pure-star-shaper', 'Star Shaper', 'Keune So Pure', 'So Pure Star Shaper maîtrise tous les styles ! Tenue forte, brillance naturelle et souplesse pour du volume et du soutien. Enrichi en huile d''argan bio et fécule de maïs , il texturise, renforce et hydrate grâce aux huiles essentielles d''orange et palmarosa.', 55.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/so-pure-star-shaper.webp', 'cheveux', 12, 284, true),
  ('sp-texture-spray', 'Texture Spray', 'Keune So Pure', 'Boostez volume et texture avec So Pure Texture Spray ! Tenue souple (niveau 9), brillance naturelle et cheveux nourris grâce à l''huile d''argan bio. Idéal pour cheveux fins, son parfum d''huiles essentielles sublime votre style en toute légèreté.', 71.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/sp-texture-spray.webp', 'cheveux', 12, 285, true),
  ('style-blowout-gelee-200ml', 'Blowout Gelee 200ml', 'Keune Style', 'Style Blowout Gelée N°56 vous donne le coup de pouce de volume dont vous avez besoin et laisse vos cheveux naturellement brillants. Les cheveux particulièrement épais revivent grâce à cette lotion volumisante – tout en étant plus faciles à coiffer.', 60.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/style-blowout-gelee-200ml.webp', 'cheveux', 12, 286, true),
  ('style-brilliant-gloss-spray-500ml', 'Brilliant Gloss Spray 500ml', 'Keune Style', 'Briller comme un diamant tous les jours ? Un spray brillant pour vos cheveux est la touche finale ultime. Que vous alliez à un gala, ou simplement au supermarché. Avec le spray brillant Style Brilliant N°110, vous serez éblouissante à chaque instant de la journée.', 143.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/style-brilliant-gloss-spray-500ml.webp', 'cheveux', 12, 287, true),
  ('style-brilliantine-gel-125ml', 'Brilliantine Gel 125ml', 'Keune Style', 'Ce n''est pas votre gel capillaire traditionnel. Le N° 29 Gel Brillantine combine le meilleur de 2 mondes : le gel et la pommade. Nous l''avons formulé pour ajouter une belle touche de tenue souple.', 60.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/style-brilliantine-gel-125ml.webp', 'cheveux', 12, 288, true),
  ('style-curl-cream-200ml', 'Curl Cream 200ml', 'Keune Style', 'Les boucles n''aiment pas rester immobiles – elles aiment l''espace et le mouvement. La crème Style Curl N°25 donne à vos cheveux bouclés ou ondulés la liberté de mouvement dont ils ont besoin.', 62.7, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/style-curl-cream-200ml.webp', 'cheveux', 12, 289, true),
  ('style-defrizz-serum-30ml', 'Defrizz Serum 30ml', 'Keune Style', 'Après le coiffage, vos cheveux peuvent friser très rapidement. Dans ces moments-là, un sérum capillaire vient à la rescousse. Le Style Defrizz Serum N°17 garde vos cheveux non seulement sans frisottis, mais aussi sains et souples.', 88.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/style-defrizz-serum-30ml.webp', 'cheveux', 12, 290, true),
  ('style-fiber-wax-125ml', 'Fiber Wax 125ml', 'Keune Style', 'La cire Style Fiber Wax N°46 est pleine de fibres, pour une tenue flexible. Elle donne du volume à vos cheveux sans les alourdir. Et en plus, cette cire légère pour cheveux offre une belle texture et une brillance naturelle. Idéale pour donner à vos cheveux n''importe quelle forme !', 60.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/style-fiber-wax-125ml.png', 'cheveux', 12, 291, true),
  ('style-forming-wax-125ml', 'Forming Wax 125ml', 'Keune Style', 'L''ingrédient secret pour un look parfait à la sortie du lit ? Vous le trouvez tout simplement dans la nature ! La cire coiffante N°57 est composée de cire d''abeille naturelle. Elle aide à lutter contre la déshydratation et donne à vos cheveux une belle brillance.', 60.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/style-forming-wax-125ml.webp', 'cheveux', 12, 292, true),
  ('style-forming-wax-75ml', 'Forming Wax 75ml', 'Keune Style', 'L''ingrédient secret pour un look parfait à la sortie du lit ? Vous le trouvez tout simplement dans la nature ! La cire coiffante N°57 est composée de cire d''abeille naturelle. Elle aide à lutter contre la déshydratation et donne à vos cheveux une belle brillance.', 60.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/style-forming-wax-75ml.webp', 'cheveux', 12, 293, true),
  ('style-freestyle-spray-500ml', 'Freestyle Spray 500ml', 'Keune Style', 'Nous aimons les joies d''une bonne laque, mais l''effet casque est tellement dépassé. C''est pourquoi nous avons développé la Laque Freestyle N° 86. Pour une tenue forte, toute la journée, qui fixe les cheveux et leur donne une brillance naturelle, mais qui respecte aussi la liberté de mouvement des cheveux.', 143.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/style-freestyle-spray-500ml.webp', 'cheveux', 12, 294, true),
  ('style-high-impact-spray-300ml', 'High Impact Spray 300ml', 'Keune Style', 'Le Style High Impact Spray N°106 est un must-have. Cette laque ferme fait en sorte que chaque cheveu reste exactement là où vous le voulez. Avec un facteur de résistance de 10, vous pouvez toujours compter sur ce spray. Qu''il pleuve ou qu''il vente, vous pouvez toujours quitter la maison sans souci.', 66.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/style-high-impact-spray-300ml.webp', 'cheveux', 12, 295, true),
  ('style-instant-blowout-200ml', 'Instant Blowout 200ml', 'Keune Style', 'Le brushing est souvent une véritable corvée. Le Style Instant Blowout N°37 le rend plus rapide et plus facile ! Ce spray volume offre une protection thermique à vos cheveux jusqu''à 230°C. Surtout pour les cheveux fins, c''est un must.', 60.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/style-instant-blowout-200ml.webp', 'cheveux', 12, 296, true),
  ('style-matte-cream-75ml', 'Matte Cream 75ml', 'Keune Style', 'Cheveux fins, épais, bouclés ou raides – avec la crème Style Matte N°62, vous avez toujours ce qu''il vous faut. Cette crème capillaire polyvalente apporte exactement le soin et la force que chaque type de cheveux peut utiliser.', 60.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/style-matte-cream-75ml.webp', 'cheveux', 12, 297, true),
  ('style-shaping-fibres-75ml', 'Shaping Fibres 75ml', 'Keune Style', 'Vous recherchez un produit de haute qualité pour une texture supplémentaire et une brillance éclatante ? Levez les mains pour les Fibres de Style Shaping N°38 ! Littéralement. Car cette cire capillaire contient des fibres que vous activez en tapant dans vos mains.', 60.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/style-shaping-fibres-75ml.webp', 'cheveux', 12, 298, true),
  ('style-soft-set-spray-300ml', 'Soft Set Spray 300ml', 'Keune Style', 'Vous travaillez sur les dernières touches d''une superbe coiffure ? Notre N° 57 Laque légère offre une tenue légère et souple, pour que vous puissiez continuer à vous coiffer. Vous pouvez aussi l''utiliser comme protection contre la lumière et pour ajouter une brillance naturelle.', 60.5, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/style-soft-set-spray-300ml.webp', 'cheveux', 12, 299, true),
  ('style-spray-wax-200ml', 'Spray Wax 200ml', 'Keune Style', 'Créez une texture aérée, facile à construire et une tenue durable avec la cire en spray N° 46. Cette brume de cire ultrafine ajoute une brillance et une définition naturelles à tous les types de cheveux, avec un fini non gras. Vous pouvez même l''utiliser pour lisser les frisottis et les cheveux rebelles.', 132.0, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/style-spray-wax-200ml.webp', 'cheveux', 12, 300, true),
  ('style-straight-cream-200ml', 'Straight Cream 200ml', 'Keune Style', '', 62.7, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/style-straight-cream-200ml.webp', 'cheveux', 12, 301, true),
  ('style-ultra-gel-200ml', 'Ultra Gel 200ml', 'Keune Style', 'Notre Gel tenue forte N° 88 offre une structure, de la brillance et une incroyable tenue. C''est un gel pour les coiffures d''aujourd''hui et pour les personnes qui aiment la brillance intense. Alors, faites des folies et sculptez ou coiffez comme vous le souhaitez.', 62.7, null, 'https://sybrraiyllmhlkwbfcod.supabase.co/storage/v1/object/public/media/produits/style-ultra-gel-200ml.webp', 'cheveux', 12, 302, true)
